    private int readPointer;

    public ClassFileBuffer(int size) {
        buffer = new byte[size];
        readPointer = 0;
    }

    public void readFrom(InputStream in) throws IOException {
        if (in == null) {
            throw new IllegalArgumentException("Input stream cannot be null");
        }
        if (!in.markSupported()) {
            throw new UnsupportedOperationException("Input stream does not support mark");
        }
        in.mark(0);
        int read = 0;
        int size = buffer.length;
        while (read < size) {
            int n = in.read(buffer, readPointer, size - read);
            if (n == -1) {
                break;
            }
            read += n;
            readPointer += n;
        }
        if (read < size) {
            throw new IOException("Could not read enough bytes from input stream");
        }
        readPointer = 0;
    }
}

